--Npc函数接入
function ServerTrip_MainNpc()

	local nNpcId = 8715
	local sUserName = Get_UserName()
	local newStr = string.sub(sUserName,-4)
	if newStr == "[GM]" then 
		 LinkNpcGossipFunc_New(nNpcId,"9-1")
	else 
		ServerTrip_ServerGroup(nNpcId)
	end 
end 

function ServerTrip_GoServer()
	local nUserId = Get_UserId()
	local nFrontierServerID = Get_FrontierServerID()
	if Sys_EnterServer(nFrontierServerID,12,nUserId,9) then
		--Sys_MsgBox(tServerTrip_Text["IntoServer"])
	end
end 

--判断跨服
function ServerTrip_ServerGroup(nNpcId)
	local sServerName = Get_SysServerName()
    LinkNpcGossipFunc_New(nNpcId,tServerTrip_Text[sServerName])
end 

function ServerTrip_EmergencyAccountIDCheck()
	local nNpcId = Get_NpcId()
	local nUserAccountID = Get_UserAccountId()
	for i,v in ipairs(tEmergencyAccounts) do
		if v == nUserAccountID then
			LinkNpcGossipFunc_New(nNpcId,"11-1")
			return true
		end
	end
	return false
end

function ServerTrip_Emergency(nIndex)
	local nNpcId = Get_NpcId()
	Sys_DialogText("请输入npcid或者物品type。")
	Sys_DialogOptEdit(tServerTrip_Text[nNpcId]["InPut"],16,"ServerTrip_Emergency1</N>" .. nIndex)
	Sys_DialogFace(nNpcId)
	Sys_DialogEnd()
end

function ServerTrip_Emergency1(nIndex)
	local nWord = tonumber(Get_SysAcceptStr())
	if nIndex == 1 then
		Npc_MoveNpcPos(nWord,5000,100,100)
	elseif nIndex == 2 then
		MoveNpc_ChgNpcActivetyTime(nWord)
	elseif nIndex == 3 then
		if tNpcGossip[nWord] ~= nil then
			tNpcGossip[nWord]["Emergency"] = 1
		end
	else
		if tItem[nWord] ~= nil then
			tItem[nWord]["Emergency"] = 1
		end
	end
	
	Sys_SaveActionFestivalLog(string.format("0,0,0,0,10002423,1[%s],%s,1",nIndex,nWord))
end 


