function ServerTrip_MoveGlobalServer(nIndex)
	local nUserId = Get_UserId()
	if nIndex ~= nil then
		Sys_EnterServer(998,12,nUserId)
	else
		Sys_EnterServer(999,12,nUserId)
	end
end


-- 移走德州桌子
function ServerTrip_MoveTexasTable()
	Npc_DelDynaNpc(1036,"id",3005)
	Npc_DelDynaNpc(1036,"id",3006)
	Npc_DelDynaNpc(1036,"id",3007)
end

-- 移动NPC
function ServerTrip_MoveNpcPos(nIndex,sText)
	local nNpcId = Get_NpcId()
	if nIndex == 1 then
		tNpcPos = {}
	end
	Sys_DialogText(sText)
	Sys_DialogOptEdit(tServerTrip_Text[nNpcId]["InPut"],16,"ServerTrip_Record</N>" .. nIndex)
	Sys_DialogFace(nNpcId)
	Sys_DialogEnd()
end

-- 记录要移走的NPC数据
function ServerTrip_Record(nIndex)
	local nWord = tonumber(Get_SysAcceptStr())
	table.insert(tNpcPos,nIndex,nWord)
	
	if nIndex == 1 then
		ServerTrip_MoveNpcPos(2,"Enter the map ID you want to move to")
	elseif nIndex == 2 then
		ServerTrip_MoveNpcPos(3,"Enter the map X coordinate to move to")
	elseif nIndex == 3 then
		ServerTrip_MoveNpcPos(4,"Enter the map Y coordinate to move to")
	elseif nIndex == 4 then
		Npc_MoveNpcPos(tNpcPos[1],tNpcPos[2],tNpcPos[3],tNpcPos[4])
		tNpcPos = {}
	end
end

function ServerTrip_Judge(nNpcId,nIndex,sText)
	local sWord = Get_SysAcceptStr()
	if sWord == tServerTrip_Text[nNpcId]["Test"] then
		ServerTrip_ServerGroup(nNpcId)
	elseif sWord == tServerTrip_Text[nNpcId]["Test1"] then
		ServerTrip_ChangeGlobal(nIndex,sText)
	end
end 

function ServerTrip_MoveNpc(nNpcId,nIndex,sText)
	Sys_DialogText(tServerTrip_Text[nNpcId]["Text55"])
	Sys_DialogOptEdit(tServerTrip_Text[nNpcId]["InPut"],16,"ServerTrip_Judge</N>"..nNpcId .. "</N>" .. nIndex .. "</S>" .. sText)
	Sys_DialogFace(nNpcId)
	Sys_DialogEnd()
end

function ServerTrip_ChangeGlobal(nIndex,sText)
	local sUserName = Get_UserName()
	local newStr = string.sub(sUserName,-4)
	local nNpcId = Get_NpcId()

	if newStr == "[GM]" then 
	
		if nIndex == 1 then
			tGlobalInfoooo = {}
		end	
		
		Sys_DialogText(sText)
		Sys_DialogOptEdit(tServerTrip_Text[nNpcId]["InPut"],16,"ServerTrip_ChangeGlobalRecord</N>" .. nIndex)
		Sys_DialogFace(nNpcId)
		Sys_DialogEnd()
	end
	
end

function ServerTrip_ChangeGlobalRecord(nIndex)
	local nWord = tonumber(Get_SysAcceptStr())
	table.insert(tGlobalInfoooo,nIndex,nWord)

	if nIndex == 1 then
		ServerTrip_ChangeGlobal(2,"Enter the Global pos you want to change")
	elseif nIndex == 2 then
		ServerTrip_ChangeGlobal(3,"Enter the Global data you want to change")
	elseif nIndex == 3 then
		Sys_SetSynaGlobalData(tGlobalInfoooo[1],tGlobalInfoooo[2],tGlobalInfoooo[3])
		tGlobalInfoooo = {}		
	end
end 
